<?php
// One-time (v3.34.1, the owner 2026-11-21: «اريد ان تنشئ رابط معاينة للوحة المطور»): adds …/v/<address>/platform — the platform's own developer
// panel (subscribers, plans, prices, payments, countries) as an example with sample data that lives only in the visitor's browser.
// Exact text replacements (each must match once) on four files whose current content is checked first; backups OUTSIDE public_html;
// `php tpp.php rollback` puts the latest backup back. Nothing else on the site changes.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$D = '/home/u791571885/domains/dar.ink/public_html'; $BK = '/home/u791571885/pv-backup';
$FILES = ['assets/edition.js', 'assets/ui.js', 'assets/core.js', 'dar-preview.php'];
$o = [];
if (($argv[1] ?? '') === 'rollback') {
    $dirs = glob("$BK/platform-*", GLOB_ONLYDIR) ?: []; sort($dirs); $last = end($dirs);
    if (!$last) { echo json_encode(['rollback' => 'no backup']), "\n"; exit; }
    foreach ($FILES as $f) if (is_file("$last/" . basename($f))) copy("$last/" . basename($f), "$D/$f");
    echo json_encode(['rolled_back_from' => $last]), "\n"; exit;
}
// the content each file has now (seen from the live site before this script was written)
$EXPECT = ['assets/edition.js' => ['sha256', 'cdb627b7f13af1fe'], 'assets/ui.js' => ['sha256', '127c4bb80c9a88c4'], 'assets/core.js' => ['sha256', '96fabd6679cff372'], 'dar-preview.php' => ['md5', '2467aec15b5e78cee7377445d5d57f29']];
$AFTER = ['dar-preview.php' => 'e4e0ae91ab4508e6ee7ded57790d602d']; // (byte-identical to the copy linted and tested before)
$R = json_decode(base64_decode(''), true);
$new = [];
foreach ($FILES as $f) {
    $s = (string)file_get_contents("$D/$f");
    if (strpos($s, 'PV_PLATFORM') !== false || strpos($s, "'platform' => ['developer'") !== false) { $o['error'] = "$f already has the platform preview"; echo json_encode($o), "\n"; exit; }
    [$alg, $want] = $EXPECT[$f]; $have = hash($alg, $s); if (strpos($have, $want) !== 0) { $o['error'] = "$f changed since it was checked ($have)"; echo json_encode($o), "\n"; exit; }
    foreach ($R as $i => $x) if ($x['file'] === $f) { $n = substr_count($s, $x['old']); if ($n !== 1) { $o['error'] = "$f: anchor $i found $n times"; echo json_encode($o), "\n"; exit; } $s = str_replace($x['old'], $x['new'], $s); }
    if (isset($AFTER[$f]) && md5($s) !== $AFTER[$f]) { $o['error'] = "$f: result differs from the tested copy"; echo json_encode($o), "\n"; exit; }
    $new[$f] = $s;
}
$stamp = date('Ymd-His'); $B = "$BK/platform-$stamp"; @mkdir($B, 0700, true);
foreach ($FILES as $f) { copy("$D/$f", "$B/" . basename($f)); file_put_contents("$B/" . basename($f) . '.next', $new[$f]); }
foreach ($FILES as $f) rename("$B/" . basename($f) . '.next', "$D/$f");
foreach (glob("$BK/*.new") ?: [] as $junk) @unlink($junk); // (left by an earlier attempt that never changed the site)
if (function_exists('opcache_reset')) @opcache_reset();
$o['state'] = 'done'; $o['backup'] = $B;
foreach ($FILES as $f) $o['now'][$f] = md5_file("$D/$f");
echo json_encode($o, JSON_UNESCAPED_SLASHES), "\n";
